import{_ as n,C as e,c as o,o as s,aa as p,G as t}from"./chunks/framework.Cn7WEiMX.js";const b=JSON.parse('{"title":"非 CraftBukkit 服务端核心支持情况","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/Dynmap/mod-support/support-for-minecraft-servers-other-than-craftbukkit.md","filePath":"wiki/Dynmap/mod-support/support-for-minecraft-servers-other-than-craftbukkit.md"}'),k={name:"wiki/Dynmap/mod-support/support-for-minecraft-servers-other-than-craftbukkit.md"};function l(u,a,h,c,d,m){const i=e("NolebaseGitContributors"),r=e("NolebaseGitChangelog");return s(),o("div",null,[a[0]||(a[0]=p(`<h1 id="非-craftbukkit-服务端核心支持情况" tabindex="-1">非 CraftBukkit 服务端核心支持情况 <a class="header-anchor" href="#非-craftbukkit-服务端核心支持情况" aria-label="Permalink to &quot;非 CraftBukkit 服务端核心支持情况&quot;">​</a></h1> <p>Dynmap 包含对其他几种服务端的支持。最新可用版本的支持情况可在<a href="http://www.minecraftforum.net/topic/1543523-dynmap-dynamic-web-based-maps-for-minecraft/" target="_blank" rel="noreferrer">这里</a>浏览。</p> <p>目前，有三种 Dynmap 平台：</p> <ul><li>Bukkit Dynmap（<a href="https://github.com/webbukkit/dynmap/" target="_blank" rel="noreferrer">https://github.com/webbukkit/dynmap/</a>）</li> <li>DynmapForge（<a href="https://github.com/webbukkit/DynmapForge/" target="_blank" rel="noreferrer">https://github.com/webbukkit/DynmapForge/</a>）</li> <li>DynmapSpout（<a href="https://github.com/webbukkit/DynmapSpout/" target="_blank" rel="noreferrer">https://github.com/webbukkit/DynmapSpout/</a>）</li></ul> <h2 id="spigot" tabindex="-1">Spigot <a class="header-anchor" href="#spigot" aria-label="Permalink to &quot;Spigot&quot;">​</a></h2> <p>Bukkit Dynmap 完全支持 Spigot。</p> <h2 id="minecraftforge" tabindex="-1">MinecraftForge <a class="header-anchor" href="#minecraftforge" aria-label="Permalink to &quot;MinecraftForge&quot;">​</a></h2> <p>DynmapForge 支持多个版本的 Forge。就像其他 Forge 模组一样，每个支持的版本都有自己的二进制值文件，更新 Forge 版本后也要更换 DynmapForge 的版本。不论升级还是初次安装，如下步骤都适用：</p> <ul><li>下载对应 MC 版本适用的 zip 压缩包。</li> <li>解压整个文件，包括文件夹，放入服务器根目录（不是 <code>mods</code> 文件夹）。</li> <li>若需要升级，请删除 <code>mods</code> 文件夹下旧版本的 <code>Dynmap-x.y.zip</code>。</li></ul> <h2 id="mcpc" tabindex="-1">MCPC+ <a class="header-anchor" href="#mcpc" aria-label="Permalink to &quot;MCPC+&quot;">​</a></h2> <p>DynmapForge 模组仅支持对应版本 Forge 的 MCPC+（1.4.7+）。不支持 CraftBukkit。只需按照上述步骤安装即可。如果需要与 Bukkit 插件联动，使用它们的 API，你可以下载安装 DynmapCBBridge 模组（点击这里前往下载。这是一个 Bukkit 插件，因此必须放入 <code>plugins</code> 目录，仅支持基于 Forge 且兼容 Bukkit 的服务器（如 MCPC+ 或 BukkitForge））。</p> <h2 id="bukkitforge" tabindex="-1">BukkitForge <a class="header-anchor" href="#bukkitforge" aria-label="Permalink to &quot;BukkitForge&quot;">​</a></h2> <p>这是一个基于 Forge 端增加了 Bukkit API 兼容性的服务端，不支持 Dynmap Bukkit 版本。但 DynmapForge 支持，可通过 DynmapCBBridge 提供的 API 兼容与其他使用了 Dynmap API 的插件交互。安装步骤与 MCPC+ 相同。</p> <h2 id="tekkit-经典版" tabindex="-1">Tekkit 经典版 <a class="header-anchor" href="#tekkit-经典版" aria-label="Permalink to &quot;Tekkit 经典版&quot;">​</a></h2> <p>Dynmap Bukkit 版本支持 Tekkie 与旧版 MCPC（适用于 1.2.5，没有加号）。这些服务端能在 1.2.5 上继续运行 Bukkit 版本的 Dynmap。</p> <h2 id="tekkit-lite" tabindex="-1">Tekkit-Lite <a class="header-anchor" href="#tekkit-lite" aria-label="Permalink to &quot;Tekkit-Lite&quot;">​</a></h2> <p>DynmapForge 支持 Tekkit-Lite，而 Bukkit Dynmap 不支持。安装步骤与 Forge 服务端相同。</p> <h2 id="spout" tabindex="-1">Spout <a class="header-anchor" href="#spout" aria-label="Permalink to &quot;Spout&quot;">​</a></h2> <p>DynmapSpout 项目尚在开发中，支持 Spout 服务端（但目前 Spout 的持续重构导致它难以投入稳定生产环境）。在 Spout 上安装 Dynmap 与 Bukkit 类似（解压后放入 <code>plugins</code> 目录）。注意：这个项目是面向 Spout（服务端），而非 SpoutPlugin（Bukkit 插件）。SpoutPlugin 服务端支持 Bukkit 版本的 Dynmap。</p> <h2 id="从-bukkit-dynmap-迁移到-forge-的安装步骤" tabindex="-1">从 Bukkit Dynmap 迁移到 Forge 的安装步骤 <a class="header-anchor" href="#从-bukkit-dynmap-迁移到-forge-的安装步骤" aria-label="Permalink to &quot;从 Bukkit Dynmap 迁移到 Forge 的安装步骤&quot;">​</a></h2> <p>将现有的 Bukkit 配置迁移到 Forge 服务端（如 MCPC+ 或 BukkitForge），只需按照如下步骤：</p> <ul><li>将整个 <code>/plugins/dynmap</code> 文件夹（所有文件与子目录）移动到 Forge 服务器上的 <code>/dynmap</code> 文件夹中。</li> <li>编辑 <code>onfiguration.txt</code>，将 <code>render-triggers</code> 部分的配置改为如下内容：</li></ul> <div class="language-YAML vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">YAML</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    render-triggers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">blockupdate</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    #- blockupdate-with-id</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    #- lightingupdate</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">chunkpopulate</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">chunkgenerate</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    #- none</span></span></code></pre></div><ul><li>删除 <code>/plugins/dynmap.jar</code>。</li> <li>跟随上述安装步骤，安装/升级对应的 Forge 版本 Dynmap。</li></ul> `,47)),t(i),t(r)])}const f=n(k,[["render",l]]);export{b as __pageData,f as default};
